def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def hidden_rule_fn(state):
    n = len(state)
    if n < 2:
        return state + [0]
    a = state[n-2]
    b = state[n-1]
    if is_prime(n):
        new_val = (a ^ b) % 7
    else:
        new_val = (a + b + 3) % 7
    return state + [new_val]
